// This file is generated by AI.

// 编辑角色对话框。
//
// 角色的全部可编辑内容都在这里: 名称 / ID / 星标 / 启用 / 两个 GSOV 模型 / 描述,
// 以及**下方的参考音频编辑列表** (增删与试听)。
//
// 为什么要把参考音频编辑放进来: 之前它藏在「选择角色」对话框里, 而那个对话框的职责
// 是"挑选参与配音的角色", 点一行就跳去编辑参考音频并不符合直觉。角色信息与它的
// 参考音频本来就该在同一个地方编辑。

import { Button, Field, Input, Switch, Textarea } from '@fluentui/react-components';
import { AddRegular, ArrowDownloadRegular, DeleteRegular, PlayRegular, StopRegular } from '@fluentui/react-icons';
import { save as saveDialog } from '@tauri-apps/plugin-dialog';
import { useEffect, useRef, useState } from 'react';

import type { Character, ModelCandidate, ReferenceAudio } from '../commands/voice';
import { voiceExportCharacter, voiceListCharacters, voiceReadAudio, voiceRemoveReference } from '../commands/voice';
import { AppDialog } from '../components/AppDialog';
import { Select } from '../components/Select';
import { voiceController } from './controller';
import { useAppStore } from '../state/store';
import { VoiceReferenceDialog } from './VoiceReferenceDialog';

interface Props {
  character: Character;
  models: ModelCandidate[];
  onClose: () => void;
  /** 内容已变化 (调用方可据此刷新自己持有的角色快照) */
  onChanged: () => void;
  onError: (error: string | null) => void;
}

export function RoleEditDialog({ character, models, onClose, onChanged, onError }: Props) {
  const [draft, setDraft] = useState(character);
  const [addOpen, setAddOpen] = useState(false);
  /** 已经落盘的 id; 与 `draft.id` 不同表示用户改了 id (需要搬移参考音频目录) */
  const savedId = useRef(character.id);

  useEffect(() => {
    setDraft(character);
    savedId.current = character.id;
  }, [character.id, character.updatedAt]);

  const commit = async (patch: Partial<Character>) => {
    const next = { ...draft, ...patch };
    setDraft(next);
    try {
      // 角色 id 可编辑: 它同时是配置文件名与参考音频目录名, 改名由后端连带搬移
      const previous = next.id === savedId.current ? undefined : savedId.current;
      const saved = await voiceController.persistCharacter(next, previous);
      savedId.current = saved.id;
      setDraft(saved);
      onError(null);
      onChanged();
    } catch (caught) {
      // 失败时回滚到已落盘的状态, 避免界面显示一个并不存在的 id
      setDraft((current) => ({ ...current, id: savedId.current }));
      onError(caught instanceof Error ? caught.message : String(caught));
    }
  };

  /** 重新读取该角色 (参考音频增删后同步最新内容) */
  const reload = async (id: string) => {
    try {
      const all = await voiceListCharacters();
      voiceController.setCharacters(all);
      const latest = all.find((item) => item.id === id);
      if (latest) setDraft(latest);
      onChanged();
    } catch (caught) {
      onError(caught instanceof Error ? caught.message : String(caught));
    }
  };

  const removeReference = async (reference: ReferenceAudio) => {
    try {
      const updated = await voiceRemoveReference(character.id, reference.hash);
      setDraft(updated);
      voiceController.setCharacters(
        useAppStore.getState().voiceCharacters.map((item) => (item.id === updated.id ? updated : item))
      );
      onChanged();
    } catch (caught) {
      onError(caught instanceof Error ? caught.message : String(caught));
    }
  };

  const exportCharacter = async () => {
    const destination = await saveDialog({
      defaultPath: `${draft.name}.zip`,
      filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
    });
    if (typeof destination !== 'string') return;
    await voiceExportCharacter(character.id, destination);
  };

  const modelName = (weights: string | null | undefined): string => {
    if (!weights) return '';
    return models.find((item) => item.gptWeights === weights || item.sovitsWeights === weights)?.name ?? weights;
  };

  return (
    <>
      <AppDialog
        title={`编辑角色 · ${character.name}`}
        size="large"
        height={640}
        compact
        onClose={onClose}
        footerLeading={
          <Button appearance="secondary" icon={<ArrowDownloadRegular />} onClick={() => void exportCharacter()}>
            导出角色
          </Button>
        }
        footer={
          <Button appearance="primary" onClick={onClose}>
            完成
          </Button>
        }
      >
        <div className="role-edit-form">
          <Field label="角色名">
            <Input
              value={draft.name}
              placeholder="角色名"
              onChange={(_, data) => setDraft({ ...draft, name: data.value })}
              onBlur={() => void commit({ name: draft.name })}
            />
          </Field>

          <Field label="角色 ID">
            <Input
              value={draft.id}
              placeholder="角色 ID"
              title="同时是配置文件名与 game/vocal 下的目录名"
              onChange={(_, data) => setDraft({ ...draft, id: data.value })}
              onBlur={() => void commit({ id: draft.id })}
            />
          </Field>

          <div className="role-edit-switches">
            <Switch
              checked={draft.starred}
              label="星标靠前"
              onChange={(_, data) => void commit({ starred: data.checked })}
            />
            <Switch
              checked={draft.enabled}
              label="参与配音"
              onChange={(_, data) => void commit({ enabled: data.checked })}
            />
          </div>

          <Field label="GPT-SoVITS 模型" className="role-edit-span">
            <div className="role-edit-models">
              <Select
                placeholder="选择 GPT 权重"
                value={
                  models.some((item) => item.gptWeights === draft.model?.gptWeights) ? draft.model!.gptWeights! : ''
                }
                title={modelName(draft.model?.gptWeights) || '未指定 GPT 权重'}
                options={models.map((item) => ({ value: item.gptWeights, label: item.name }))}
                onChange={(gptWeights) =>
                  void commit({
                    model: { ...(draft.model ?? {}), gptWeights },
                  })
                }
              />
              <Select
                placeholder="选择 SoVITS 权重"
                value={
                  models.some((item) => item.sovitsWeights === draft.model?.sovitsWeights)
                    ? draft.model!.sovitsWeights!
                    : ''
                }
                title={modelName(draft.model?.sovitsWeights) || '未指定 SoVITS 权重'}
                options={models.map((item) => ({ value: item.sovitsWeights, label: item.name }))}
                onChange={(sovitsWeights) =>
                  void commit({
                    model: { ...(draft.model ?? {}), sovitsWeights },
                  })
                }
              />
            </div>
          </Field>

          <Field label="描述" className="role-edit-span">
            <Textarea
              className="character-description"
              resize="vertical"
              value={draft.description}
              onChange={(_, data) => setDraft({ ...draft, description: data.value })}
              onBlur={() => void commit({ description: draft.description })}
            />
          </Field>
        </div>

        {/* 参考音频编辑列表 */}
        <div className="role-edit-references">
          <div className="role-edit-references-head">
            <span className="voice-label">参考音频（{draft.references.length}）</span>
            <span className="workbench-spacer" />
            <Button size="small" appearance="primary" icon={<AddRegular />} onClick={() => setAddOpen(true)}>
              添加参考音频
            </Button>
          </div>

          <div className="dialog-scroll">
            {draft.references.length === 0 ? (
              <p className="voice-dialog-empty">暂无参考音频。参考文本必须与音频逐字一致, 时长 3~10 秒。</p>
            ) : (
              draft.references.map((reference) => (
                <div key={reference.hash} className="reference-item">
                  <div className="reference-main">
                    <div className="reference-text">{reference.text || '（未填写参考文本）'}</div>
                    <div className="reference-meta">
                      {reference.language} · {reference.duration.toFixed(2)}s ·{' '}
                      {Math.round(reference.sampleRate / 1000)}kHz
                      {reference.tags.length > 0 && ` · ${reference.tags.join(' / ')}`}
                    </div>
                  </div>
                  <AudioButton path={voiceController.referencePathFor(character.id, reference.file)} />
                  <Button
                    size="small"
                    appearance="subtle"
                    className="danger-icon"
                    icon={<DeleteRegular />}
                    title="删除该参考音频"
                    onClick={() => void removeReference(reference)}
                  />
                </div>
              ))
            )}
          </div>
        </div>
      </AppDialog>

      <VoiceReferenceDialog
        open={addOpen}
        character={draft}
        selectedHash={null}
        onPick={() => {}}
        onClose={() => setAddOpen(false)}
        onCharactersChanged={() => void reload(character.id)}
      />
    </>
  );
}

/** 试听按钮 (全局互斥播放) */
function AudioButton({ path }: { path: string }) {
  const [playing, setPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    return () => {
      audioRef.current?.pause();
      audioRef.current = null;
    };
  }, []);

  const toggle = async () => {
    if (playing) {
      audioRef.current?.pause();
      setPlaying(false);
      return;
    }
    try {
      const dataUrl = await voiceReadAudio(path);
      document.querySelectorAll<HTMLAudioElement>('audio[data-voice-preview]').forEach((element) => element.pause());
      const audio = new Audio(dataUrl);
      audio.dataset['voicePreview'] = 'true';
      audio.onended = () => setPlaying(false);
      audio.onerror = () => setPlaying(false);
      audioRef.current = audio;
      await audio.play();
      setPlaying(true);
    } catch {
      setPlaying(false);
    }
  };

  return (
    <Button
      size="small"
      appearance="subtle"
      icon={playing ? <StopRegular /> : <PlayRegular />}
      title="试听"
      onClick={() => void toggle()}
    />
  );
}
